/** The per-org queue-depth fuse: whether to refuse a new enqueue from this org. */
export function refuseEnqueue(load: OrgLoad): boolean {
  // Cap derived from guaranteed throughput: at the org's share and a 5-minute
  // median build, an hour of queue is share × 12. Over that, the org's own
  // guaranteed concurrency would take longer to drain than anyone is willing to wait.
  const cap = load.share * 12;
  return load.queued >= cap;
}

